"""PostgreSQL adapter for the existing bounded-Goal ledger and invariants."""
from contextlib import contextmanager, nullcontext
from hashlib import sha256

import psycopg
from psycopg import sql
from psycopg.rows import dict_row

from goodteam_os.database import database, workspace_identity


TABLES = {
    "goals": "id TEXT PRIMARY KEY, project_key TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE",
    "work": "goal_id TEXT NOT NULL REFERENCES goals(id), id TEXT NOT NULL, position INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(goal_id,id), UNIQUE(goal_id,position)",
    "events": "id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES goals(id), revision INTEGER NOT NULL, kind TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(goal_id,revision)",
    "outbox": "event_id TEXT PRIMARY KEY REFERENCES events(id), goal_id TEXT NOT NULL REFERENCES goals(id), revision INTEGER NOT NULL, delivered INTEGER NOT NULL DEFAULT 0, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE",
    "operations": "project_key TEXT NOT NULL, operation_key TEXT NOT NULL, fingerprint TEXT NOT NULL, result TEXT NOT NULL, PRIMARY KEY(project_key,operation_key)",
}
COLUMNS = {
    "goals": "id,project_key,revision,data", "work": "goal_id,id,position,data",
    "events": "id,goal_id,revision,kind,data", "operations": "project_key,operation_key,fingerprint,result",
}


class GoalRow(dict):
    def __getitem__(self, key):
        return list(self.values())[key] if isinstance(key, int) else super().__getitem__(key)


def _rows(cursor):
    names = [column.name for column in cursor.description or []]
    return lambda values: GoalRow(zip(names, values))


class GoalConnection:
    def __init__(self, conn):
        self.conn = conn

    def execute(self, query, parameters=()):
        # These are fixed service SQL statements, never user/model-authored SQL.
        for name, columns in COLUMNS.items():
            query = query.replace(f"INSERT INTO {name} VALUES", f"INSERT INTO {name}({columns}) VALUES")
        return self.conn.execute(query.replace("?", "%s"), parameters)


def schema_for(workspace):
    return "gt_goals_" + sha256((database().schema + workspace_identity(workspace)).encode()).hexdigest()[:32]


def initialize(store, *, importing=False):
    from goodteam_os.goals import GoalCorruptState

    backend = database()
    store._goal_schema = schema_for(store.workspace)
    with backend.connection() as conn:
        if store.path.is_file() and not importing:
            migrated = conn.execute("SELECT 1 FROM state_imports WHERE path=%s", (str(store.path.resolve()),)).fetchone()
            if not migrated:
                raise GoalCorruptState("Existing Goal state requires an explicit PostgreSQL import before use.")
        with conn.transaction():
            conn.execute("SELECT pg_advisory_xact_lock(%s)", (_lock_key(store),))
            conn.execute(sql.SQL("CREATE SCHEMA IF NOT EXISTS {}").format(sql.Identifier(store._goal_schema)))
            tables = {row["tablename"] for row in conn.execute(
                "SELECT tablename FROM pg_tables WHERE schemaname=%s", (store._goal_schema,))}
            if not tables:
                conn.execute(sql.SQL("SET LOCAL search_path TO {}").format(sql.Identifier(store._goal_schema)))
                for name, definition in TABLES.items():
                    conn.execute(sql.SQL("CREATE TABLE {} (").format(sql.Identifier(name)) + sql.SQL(definition + ")"))
                conn.execute("CREATE TABLE ledger_metadata(version INTEGER NOT NULL)")
                conn.execute("INSERT INTO ledger_metadata VALUES (1)")
            elif tables != set(TABLES) | {"ledger_metadata"}:
                raise GoalCorruptState("Unsupported or incomplete Goal ledger; continuation is disabled.")
            rows = conn.execute(sql.SQL("SELECT version FROM {}.ledger_metadata").format(
                sql.Identifier(store._goal_schema))).fetchall()
            if rows != [{"version": 1}]:
                raise GoalCorruptState("Unsupported Goal ledger version; continuation is disabled.")


def _lock_key(store):
    return int.from_bytes(sha256(str(store.path.resolve()).encode()).digest()[:8], signed=True)


@contextmanager
def transaction(store, *, write=False, existing_connection=None):
    from goodteam_os.goals import GoalCorruptState

    try:
        scope = nullcontext(existing_connection) if existing_connection is not None else database().connection()
        with scope as conn, conn.transaction():
            if not write:
                conn.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY")
            conn.execute(sql.SQL("SET LOCAL search_path TO {}").format(sql.Identifier(store._goal_schema)))
            if write:
                conn.execute("SELECT pg_advisory_xact_lock(%s)", (_lock_key(store),))
            conn.row_factory = _rows
            try:
                yield GoalConnection(conn)
            finally:
                conn.row_factory = dict_row
    except psycopg.Error as exc:
        raise GoalCorruptState("Goal ledger could not be read or committed; continuation is disabled.") from exc


def exists(workspace):
    with database().connection() as conn:
        present = conn.execute("SELECT 1 FROM pg_tables WHERE schemaname=%s AND tablename='goals'",
                               (schema_for(workspace),)).fetchone()
    return bool(present)
